import{_ as t,o as d,c as a,Q as e}from"./chunks/framework.48927342.js";const p=JSON.parse('{"title":"餐厅晚餐——短信对话","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/07-claire-restaurant-messages.md","filePath":"zh/more/maltese/practice/dialogues/07-claire-restaurant-messages.md"}'),r={name:"zh/more/maltese/practice/dialogues/07-claire-restaurant-messages.md"},o=e('<h1 id="餐厅晚餐——短信对话" tabindex="-1">餐厅晚餐——短信对话 <a class="header-anchor" href="#餐厅晚餐——短信对话" aria-label="Permalink to &quot;餐厅晚餐——短信对话&quot;">​</a></h1><p><strong>场景：</strong> Claire 和朋友互发短信，确认今晚在餐厅晚餐的安排：见面时间、着装和孩子照看。（说话人标签根据对话语境推断。）</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>朋友：</strong> Waranofsinhar it-tajjeb, Claire. Għal illejla kollox sew?</p><p><strong>Claire：</strong> Waranofsinhar it-tajjeb. Iva għal-lejla kollox sew. Fit-tmienja u nofs hux?</p><p><strong>朋友：</strong> Eżatt, niltaqgħu fit-tmienja u nofs u nidħlu ġewwa l-ħanut.</p><p><strong>朋友：</strong> X&#39;ser tilbes?</p><p><strong>朋友：</strong> Ħa tilbes ġakketta?</p><p><strong>Claire：</strong> Qed ikun ftit bard u għalhekk naħseb nilbes ġakketta u flokk tas-suf.</p><p><strong>朋友：</strong> Tajjeb, nilbes bħalek mela. It-tifel se iġġibuh magħkom?</p><p><strong>Claire：</strong> Jien u r-raġel, it-tifel ser inħalluh m&#39;ommi.</p><p><strong>朋友：</strong> Tajjeb, niltaqgħu mela. Saħħiet.</p><p><strong>Claire：</strong> Iva, niltaqgħu. Saħħiet.</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-朋友" tabindex="-1">1. 朋友 <a class="header-anchor" href="#_1-朋友" aria-label="Permalink to &quot;1. 朋友&quot;">​</a></h3><p><strong>Malti:</strong> Waranofsinhar it-tajjeb, Claire. Għal illejla kollox sew?</p><p><strong>整句：</strong> 下午好，Claire。今晚一切都好吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Waranofsinhar</td><td>下午</td><td><code>wara</code>（之后）+ <code>nofsinhar</code>（正午）</td></tr><tr><td>it-tajjeb</td><td>好的</td><td><code>tajjeb</code> 带定冠词，问候语&quot;下午好&quot;</td></tr><tr><td>Għal</td><td>对于</td><td>介词</td></tr><tr><td>illejla</td><td>今晚</td><td><code>il-lejla</code></td></tr><tr><td>kollox</td><td>一切</td><td>不定代词</td></tr><tr><td>sew</td><td>好；顺利</td><td>副词</td></tr></tbody></table><h3 id="_2-claire" tabindex="-1">2. Claire <a class="header-anchor" href="#_2-claire" aria-label="Permalink to &quot;2. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Waranofsinhar it-tajjeb. Iva għal-lejla kollox sew. Fit-tmienja u nofs hux?</p><p><strong>整句：</strong> 下午好。是的，今晚一切都好。八点半，对吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Waranofsinhar it-tajjeb</td><td>下午好</td><td>问候语</td></tr><tr><td>Iva</td><td>是的</td><td>肯定应答</td></tr><tr><td>għal-lejla</td><td>今晚</td><td><code>għal</code>+<code>il-lejla</code></td></tr><tr><td>kollox sew</td><td>一切都好</td><td>固定搭配</td></tr><tr><td>Fit-tmienja</td><td>在八点</td><td><code>f&#39;</code>+<code>it-tmienja</code></td></tr><tr><td>u nofs</td><td>半</td><td>时间表达&quot;八点半&quot;</td></tr><tr><td>hux</td><td>对吧；是吗</td><td><code>hu</code>+<code>x</code> 疑问小词，求确认</td></tr></tbody></table><h3 id="_3-朋友" tabindex="-1">3. 朋友 <a class="header-anchor" href="#_3-朋友" aria-label="Permalink to &quot;3. 朋友&quot;">​</a></h3><p><strong>Malti:</strong> Eżatt, niltaqgħu fit-tmienja u nofs u nidħlu ġewwa l-ħanut.</p><p><strong>整句：</strong> 正是，我们八点半见，然后进店里。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Eżatt</td><td>正是；准确</td><td>借词 exact</td></tr><tr><td>niltaqgħu</td><td>我们见面</td><td>第一人称复数</td></tr><tr><td>fit-tmienja u nofs</td><td>在八点半</td><td>时间表达</td></tr><tr><td>nidħlu</td><td>我们进入</td><td>第一人称复数</td></tr><tr><td>ġewwa</td><td>里面</td><td>介词</td></tr><tr><td>l-ħanut</td><td>商店；店铺</td><td>阳性名词，带定冠词</td></tr></tbody></table><h3 id="_4-朋友" tabindex="-1">4. 朋友 <a class="header-anchor" href="#_4-朋友" aria-label="Permalink to &quot;4. 朋友&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;ser tilbes?</p><p><strong>整句：</strong> 你要穿什么？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>X&#39;</td><td>什么</td><td><code>x&#39;</code> 缩合形式</td></tr><tr><td>ser</td><td>将要</td><td>将来时标记</td></tr><tr><td>tilbes</td><td>你穿</td><td>第二人称单数</td></tr></tbody></table><h3 id="_5-朋友" tabindex="-1">5. 朋友 <a class="header-anchor" href="#_5-朋友" aria-label="Permalink to &quot;5. 朋友&quot;">​</a></h3><p><strong>Malti:</strong> Ħa tilbes ġakketta?</p><p><strong>整句：</strong> 你会穿夹克吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ħa</td><td>将要</td><td>口语将来时标记</td></tr><tr><td>tilbes</td><td>你穿</td><td>第二人称单数</td></tr><tr><td>ġakketta</td><td>夹克</td><td>借词 jacket</td></tr></tbody></table><h3 id="_6-claire" tabindex="-1">6. Claire <a class="header-anchor" href="#_6-claire" aria-label="Permalink to &quot;6. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Qed ikun ftit bard u għalhekk naħseb nilbes ġakketta u flokk tas-suf.</p><p><strong>整句：</strong> 天气有点冷，所以我想穿夹克和毛衣。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在</td><td>进行时标记</td></tr><tr><td>ikun</td><td>是</td><td><code>kun</code> 的现在时（天气）</td></tr><tr><td>ftit</td><td>有点</td><td>程度副词</td></tr><tr><td>bard</td><td>冷</td><td>名词</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>għalhekk</td><td>因此</td><td><code>għal</code>+<code>hekk</code></td></tr><tr><td>naħseb</td><td>我想</td><td>第一人称单数</td></tr><tr><td>nilbes</td><td>我穿</td><td>第一人称单数</td></tr><tr><td>flokk</td><td>毛衣；针织衫</td><td>借词</td></tr><tr><td>tas-suf</td><td>羊毛的</td><td><code>ta&#39;</code>+<code>is-suf</code></td></tr></tbody></table><h3 id="_7-朋友" tabindex="-1">7. 朋友 <a class="header-anchor" href="#_7-朋友" aria-label="Permalink to &quot;7. 朋友&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb, nilbes bħalek mela. It-tifel se iġġibuh magħkom?</p><p><strong>整句：</strong> 好的，那我也穿一样的。孩子你们会带上吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tajjeb</td><td>好的</td><td>形容词</td></tr><tr><td>nilbes</td><td>我穿</td><td>第一人称单数</td></tr><tr><td>bħalek</td><td>像你一样</td><td><code>bħal</code>+<code>-ek</code>（你的）</td></tr><tr><td>mela</td><td>那么；那好吧</td><td>口语语气词</td></tr><tr><td>It-tifel</td><td>孩子；男孩</td><td>阳性名词，带定冠词</td></tr><tr><td>se</td><td>将要</td><td>将来时标记</td></tr><tr><td>iġġibuh</td><td>你们带他</td><td><code>iġġibu</code>+<code>-h</code>（他）</td></tr><tr><td>magħkom</td><td>和你们</td><td><code>ma&#39;</code>+<code>-kom</code>（你们）</td></tr></tbody></table><h3 id="_8-claire" tabindex="-1">8. Claire <a class="header-anchor" href="#_8-claire" aria-label="Permalink to &quot;8. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Jien u r-raġel, it-tifel ser inħalluh m&#39;ommi.</p><p><strong>整句：</strong> 我和我丈夫，孩子我们会留给我妈妈。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>第一人称代词</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>r-raġel</td><td>丈夫</td><td><code>raġel</code> 带定冠词</td></tr><tr><td>it-tifel</td><td>孩子</td><td>带定冠词</td></tr><tr><td>ser</td><td>将要</td><td>将来时标记</td></tr><tr><td>inħalluh</td><td>我们留下他</td><td><code>inħallu</code>+<code>-h</code></td></tr><tr><td>m&#39;ommi</td><td>在我妈妈那里</td><td><code>ma&#39;</code>+<code>ommi</code>（我妈妈）</td></tr></tbody></table><h3 id="_9-朋友" tabindex="-1">9. 朋友 <a class="header-anchor" href="#_9-朋友" aria-label="Permalink to &quot;9. 朋友&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb, niltaqgħu mela. Saħħiet.</p><p><strong>整句：</strong> 好的，那我们见面吧。再见。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tajjeb</td><td>好的</td><td>形容词</td></tr><tr><td>niltaqgħu</td><td>我们见面</td><td>第一人称复数</td></tr><tr><td>mela</td><td>那么</td><td>语气词</td></tr><tr><td>Saħħiet</td><td>再见</td><td><code>saħħa</code> 的复数告别语</td></tr></tbody></table><h3 id="_10-claire" tabindex="-1">10. Claire <a class="header-anchor" href="#_10-claire" aria-label="Permalink to &quot;10. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Iva, niltaqgħu. Saħħiet.</p><p><strong>整句：</strong> 好的，我们见面。再见。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是的；好的</td><td>肯定应答</td></tr><tr><td>niltaqgħu</td><td>我们见面</td><td>第一人称复数</td></tr><tr><td>Saħħiet</td><td>再见</td><td>告别语</td></tr></tbody></table>',54),l=[o];function i(n,s,h,c,b,u){return d(),a("div",null,l)}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
